fn reverse_upto_k(s: &mut Vec<i32>, k: usize) {
    // Reverse the first k elements in place
    let mut left = 0;
    let mut right = k - 1;
    while left < right {
        s.swap(left, right);
        left += 1;
        right -= 1;
    }
}